void scsi_abort_complete(struct scsi_cmnd *cmd) {
    struct Scsi_Host *host = cmd->host;

    /* Ensure the command is not in a state where it can race with driver completions */
    spin_lock_irq(&host->host_lock);

    /* Move the command to the error handler queue and remove it from the pending list */
    list_del_init(&cmd->eh_entry);
    list_add_tail(&cmd->eh_entry, &host->eh_done_q);

    spin_unlock_irq(&host->host_lock);

    /* Complete the command to signal abort completion */
    scsi_finish_command(cmd);
}
